Lemma bridge_out : SBR.out_check F0 LibSegEb_dpX2_pre_rc2.F0 = true. Proof. vm_compute. reflexivity. Qed.
Lemma bridge_rok : SBR.rok_check F0 LibSegEb_dpX2_pre_rc2.F0 = true. Proof. vm_compute. reflexivity. Qed.
Lemma bridge_pss : SBR.pss_check PSS LibSegEb_dpX2_pre_rc2.PSS = true. Proof. vm_compute. reflexivity. Qed.
